{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.LOGIC_UC_INVENTORY_RECON AS WITH params AS ( SELECT ARRAY_CONSTRUCT() AS p_sku_list, NULL::STRING AS p_sku_pattern, NULL::STRING AS p_brand, NULL::STRING AS p_category, NULL::STRING AS p_size, NULL::STRING AS p_colour, ARRAY_CONSTRUCT(2, 8, 94) AS p_branches, 0::NUMBER AS p_min_abs_diff ), excluded_skus AS ( SELECT DISTINCT UPPER(TRIM(\"Item SkuCode\")) AS sku FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_LIVE_INVENTORY WHERE NULLIF(TRIM(\"Item SkuCode\"), \'\') IS NOT NULL AND ( UPPER(TRIM(COALESCE(\"Category Name\",\'\'))) IN (\'NON- TRADING\',\'NON-TRADING\',\'CARRY BAG\') OR UPPER(TRIM(COALESCE(BRAND,\'\'))) = \'GENERAL\' OR UPPER(TRIM(\"Item SkuCode\")) LIKE \'NT%\' OR UPPER(TRIM(\"Item SkuCode\")) LIKE \'CBB%\' OR UPPER(TRIM(\"Item SkuCode\")) LIKE \'TEST%\' OR UPPER(TRIM(\"Item SkuCode\")) LIKE \'%HANGER%\' OR REGEXP_LIKE(UPPER(TRIM(\"Item SkuCode\")), \'^[0-9]+$\') ) ), sku_attr AS ( SELECT UPPER(TRIM(\"Item SkuCode\")) AS sku, MAX(\"Category Name\") AS category_name, MAX(BRAND) AS brand, MAX(SIZE) AS size, MAX(COLOR) AS colour, MAX(\"Item Type Name\") AS item_type, MAX(EAN) AS ean FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_LIVE_INVENTORY WHERE NULLIF(TRIM(\"Item SkuCode\"), \'\') IS NOT NULL GROUP BY 1 ), uc_stock AS ( SELECT CASE UPPER(TRIM(u.FACILITY)) WHEN \'SAPL-WH1\' THEN 2 WHEN \'SAPL-WH2\' THEN 8 WHEN \'SAPL-NORTH-TAURU\' THEN 94 END AS branch_code, UPPER(TRIM(u.\"Item SkuCode\")) AS sku, SUM(COALESCE(u.INVENTORY,0)) AS uc_good, SUM(COALESCE(u.\"Inventory Blocked\",0)) AS uc_blocked, SUM(COALESCE(u.\"Bad Inventory\",0)) AS uc_bad, SUM(COALESCE(u.\"Inventory Not Synced\",0)) AS uc_not_synced, SUM(COALESCE(u.\"Stock In Transfer\",0)) AS uc_in_transfer, SUM(COALESCE(u.\"Putaway Pending\",0)) AS uc_putaway_pending, SUM(COALESCE(u.\"Putback Pending\",0)) AS uc_putback_pending FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_LIVE_INVENTORY u WHERE UPPER(TRIM(u.FACILITY)) IN (\'SAPL-WH1\',\'SAPL-WH2\',\'SAPL-NORTH-TAURU\') AND NULLIF(TRIM(u.\"Item SkuCode\"), \'\') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM excluded_skus x WHERE x.sku = UPPER(TRIM(u.\"Item SkuCode\"))) GROUP BY 1, 2 ), logic_date AS ( SELECT BRANCH_CODE, MAX(DATE) AS stock_date FROM SNITCH_DB.MAPLEMONK.LOGICERP_WAREHOUSE_GET_STOCK_IN_HAND WHERE BRANCH_CODE IN (2, 8, 94) GROUP BY BRANCH_CODE ), logic_stock AS ( SELECT l.DATE AS stock_date, l.BRANCH_CODE AS branch_code, UPPER(TRIM(l.ADDLITEMCODE)) AS sku, SUM(IFF(UPPER(TRIM(l.GODOWN_NAME))=\'GOOD_INVENTORY\', COALESCE(l.STOCK_QTY,0), 0)) AS logic_good, SUM(IFF(UPPER(TRIM(l.GODOWN_NAME))=\'BAD_INVENTORY\', COALESCE(l.STOCK_QTY,0), 0)) AS logic_bad FROM SNITCH_DB.MAPLEMONK.LOGICERP_WAREHOUSE_GET_STOCK_IN_HAND l JOIN logic_date d ON d.BRANCH_CODE = l.BRANCH_CODE AND l.DATE = d.stock_date WHERE l.BRANCH_CODE IN (2, 8, 94) AND UPPER(TRIM(l.GODOWN_NAME)) IN (\'GOOD_INVENTORY\',\'BAD_INVENTORY\') AND NULLIF(TRIM(l.ADDLITEMCODE), \'\') IS NOT NULL AND UPPER(TRIM(l.ADDLITEMCODE)) NOT LIKE \'NT%\' AND UPPER(TRIM(l.ADDLITEMCODE)) NOT LIKE \'CBB%\' AND UPPER(TRIM(l.ADDLITEMCODE)) NOT LIKE \'TEST%\' AND UPPER(TRIM(l.ADDLITEMCODE)) NOT LIKE \'%HANGER%\' AND NOT REGEXP_LIKE(UPPER(TRIM(l.ADDLITEMCODE)), \'^[0-9]+$\') AND NOT EXISTS (SELECT 1 FROM excluded_skus x WHERE x.sku = UPPER(TRIM(l.ADDLITEMCODE))) GROUP BY 1, 2, 3 ), reco AS ( SELECT COALESCE(lg.stock_date, (SELECT MAX(stock_date) FROM logic_date)) AS stock_date, COALESCE(uc.branch_code, lg.branch_code) AS branch_code, CASE COALESCE(uc.branch_code, lg.branch_code) WHEN 2 THEN \'SAPL-WH1\' WHEN 8 THEN \'SAPL-WH2\' WHEN 94 THEN \'SAPL-NORTH-TAURU\' END AS uc_facility, CASE COALESCE(uc.branch_code, lg.branch_code) WHEN 2 THEN \'SNITCH - WH - YELHANKA\' WHEN 8 THEN \'SNITCH - WH - YELHANKA 2\' WHEN 94 THEN \'SNITCH - WH - NORTH\' END AS logic_warehouse, COALESCE(uc.sku, lg.sku) AS sku, COALESCE(uc.uc_good,0) AS uc_good, COALESCE(uc.uc_blocked,0) AS uc_blocked, COALESCE(uc.uc_bad,0) AS uc_bad, COALESCE(uc.uc_not_synced,0) AS uc_not_synced, COALESCE(uc.uc_in_transfer,0) AS uc_in_transfer, COALESCE(uc.uc_putaway_pending,0) AS uc_putaway_pending, COALESCE(uc.uc_putback_pending,0) AS uc_putback_pending, COALESCE(uc.uc_good,0)+COALESCE(uc.uc_blocked,0)+COALESCE(uc.uc_bad,0)+COALESCE(uc.uc_not_synced,0) AS uc_stock, COALESCE(uc.uc_good,0)+COALESCE(uc.uc_blocked,0)+COALESCE(uc.uc_bad,0)+COALESCE(uc.uc_not_synced,0) +COALESCE(uc.uc_putaway_pending,0)+COALESCE(uc.uc_putback_pending,0) AS uc_stock_all, COALESCE(lg.logic_good,0) AS logic_good, COALESCE(lg.logic_bad,0) AS logic_bad, COALESCE(lg.logic_good,0)+COALESCE(lg.logic_bad,0) AS logic_stock, uc.sku IS NULL AS missing_in_uc, lg.sku IS NULL AS missing_in_logic FROM uc_stock uc FULL OUTER JOIN logic_stock lg ON uc.branch_code = lg.branch_code AND uc.sku = lg.sku ) SELECT r.stock_date, r.branch_code, r.uc_facility, r.logic_warehouse, r.sku, a.brand, a.category_name, a.item_type, a.size, a.colour, a.ean, r.uc_good, r.uc_blocked, r.uc_bad, r.uc_not_synced, r.uc_in_transfer, r.uc_putaway_pending, r.uc_putback_pending, r.uc_stock, r.uc_stock_all, r.logic_good, r.logic_bad, r.logic_stock, r.uc_stock - r.logic_stock AS uc_minus_logic, r.uc_stock_all - r.logic_stock AS uc_all_minus_logic, ABS(r.uc_stock_all - r.logic_stock) AS abs_diff_all, CASE WHEN r.missing_in_uc THEN \'MISSING_IN_UC\' WHEN r.missing_in_logic THEN \'MISSING_IN_LOGIC\' WHEN r.uc_stock = r.logic_stock THEN \'MATCHED\' ELSE \'MISMATCH\' END AS status_original_formula, CASE WHEN r.missing_in_uc THEN \'MISSING_IN_UC\' WHEN r.missing_in_logic THEN \'MISSING_IN_LOGIC\' WHEN r.uc_stock_all = r.logic_stock THEN \'MATCHED\' ELSE \'MISMATCH\' END AS status, CASE WHEN r.uc_stock_all > r.logic_stock THEN \'UC_OVERSTATES\' WHEN r.uc_stock_all < r.logic_stock THEN \'UC_UNDERSTATES\' ELSE \'EQUAL\' END AS direction_vs_logic FROM reco r CROSS JOIN params p LEFT JOIN sku_attr a ON a.sku = r.sku WHERE GREATEST(ABS(r.uc_stock_all), ABS(r.uc_stock), ABS(r.logic_stock)) > 0 AND ARRAY_CONTAINS(r.branch_code::VARIANT, p.p_branches) AND (ARRAY_SIZE(p.p_sku_list) = 0 OR ARRAY_CONTAINS(r.sku::VARIANT, p.p_sku_list)) AND (p.p_sku_pattern IS NULL OR r.sku LIKE UPPER(p.p_sku_pattern)) AND (p.p_brand IS NULL OR UPPER(TRIM(a.brand)) = UPPER(TRIM(p.p_brand))) AND (p.p_category IS NULL OR UPPER(TRIM(a.category_name)) = UPPER(TRIM(p.p_category))) AND (p.p_size IS NULL OR UPPER(TRIM(a.size)) = UPPER(TRIM(p.p_size))) AND (p.p_colour IS NULL OR UPPER(TRIM(a.colour)) = UPPER(TRIM(p.p_colour))) AND abs_diff_all >= p.p_min_abs_diff ORDER BY abs_diff_all DESC, r.branch_code, r.sku ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            